ReplacementContent:
"    // Restore covers
    setCoversCount(receipt.covers || '');

    // Restore waiter
    if (receipt.waiter_id) {
      setSelectedWaiter({ id: receipt.waiter_id, name: receipt.waiter_name || 'Waiter' });
    } else {
      setSelectedWaiter(null);
    }

    // Track that we are editing this order
    setEditingOrder(receipt);"

